const viewer = (window.viewer = new Cesium.Viewer('cesiumContainer', {
  baseLayer: new Cesium.ImageryLayer(new Cesium.OpenStreetMapImageryProvider({
    url: 'https://tile.openstreetmap.org/',
    maximumLevel: 18
  })),
  baseLayerPicker: false,
  navigationHelpButton: false,
  animation: false,
  timeline: false,
  geocoder: false,
  homeButton: false,
  sceneModePicker: false,
  fullscreenButton: false,
  infoBox: false,
  selectionIndicator: false
}));

viewer.scene.globe.enableLighting = false;

// Define coordinates
const nycLon = -74.0060;
const nycLat = 40.7128;
const parisLon = 2.3522;
const parisLat = 48.8566;

// Convert to Cartographic (radians)
const nycCarto = Cesium.Cartographic.fromDegrees(nycLon, nycLat);
const parisCarto = Cesium.Cartographic.fromDegrees(parisLon, parisLat);

// Construct EllipsoidGeodesic
const geodesic = new Cesium.EllipsoidGeodesic(nycCarto, parisCarto);

// Read surface distance in metres
const surfaceDistanceMetres = geodesic.surfaceDistance;
const surfaceDistanceKm = Math.round(surfaceDistanceMetres / 1000);

// Sample 64 intermediate points along the geodesic
const numSamples = 64;
const positions = [];
for (let i = 0; i <= numSamples; i++) {
  const t = i / numSamples;
  const intermediateCarto = geodesic.interpolateUsingFraction(t);
  const cartesian = Cesium.Cartesian3.fromRadians(
    intermediateCarto.longitude,
    intermediateCarto.latitude,
    0.0
  );
  positions.push(cartesian);
}

// Add polyline entity
viewer.entities.add({
  polyline: {
    positions: positions,
    width: 4,
    material: Cesium.Color.YELLOW,
    clampToGround: true
  }
});

// Midpoint at t=0.5
const midCarto = geodesic.interpolateUsingFraction(0.5);
const midCartesian = Cesium.Cartesian3.fromRadians(
  midCarto.longitude,
  midCarto.latitude,
  0.0
);

// Add label entity at midpoint
viewer.entities.add({
  position: midCartesian,
  label: {
    text: `Distance: ${surfaceDistanceKm} km`,
    font: '16pt sans-serif',
    fillColor: Cesium.Color.WHITE,
    outlineColor: Cesium.Color.BLACK,
    outlineWidth: 2,
    style: Cesium.LabelStyle.FILL_AND_OUTLINE,
    verticalOrigin: Cesium.VerticalOrigin.BOTTOM,
    pixelOffset: new Cesium.Cartesian2(0, -10),
    disableDepthTestDistance: Number.POSITIVE_INFINITY
  }
});

// Frame camera over the North Atlantic (~47N, -35W, 10,000,000m altitude)
viewer.camera.setView({
  destination: Cesium.Cartesian3.fromDegrees(-35.0, 47.0, 10000000.0),
  orientation: {
    heading: Cesium.Math.toRadians(0.0),
    pitch: Cesium.Math.toRadians(-90.0),
    roll: 0.0
  }
});
